@dataclass(frozen=True)
class ContextQuery:
    period_end: Optional[date] = None
    period: str = "quarter"
    scope: StatementScope = StatementScope.UNKNOWN
    current: bool = True

    def __post_init__(self) -> None:
        if self.period not in ("quarter", "year_to_date", "instant"):
            raise ValueError("period must be quarter, year_to_date, or instant")


class MetricMapper:
    """Maps facts by local-name aliases while retaining raw facts unchanged."""

    def __init__(
        self, aliases: Optional[Mapping[str, Sequence[str]]] = None
    ) -> None:
        merged = {name: tuple(values) for name, values in DEFAULT_ALIASES.items()}
        if aliases:
            for name, values in aliases.items():
                merged[name] = tuple(values)
        self.aliases = merged
        self._concept_to_metric = {
            _normalized(alias): metric
            for metric, concepts in merged.items()
            for alias in concepts
        }
        self._alias_rank = {
            (metric, _normalized(alias)): index
            for metric, concepts in merged.items()
            for index, alias in enumerate(concepts)
        }

    def map_filing(
        self, filing: ParsedFiling, query: ContextQuery
    ) -> Tuple[MetricRecord, ...]:
        target_end = query.period_end or _target_accounting_date(filing.facts, query)
        if target_end is None:
            return ()
        candidates: Dict[str, List[FactRecord]] = {}
        for fact in filing.facts:
            if fact.numeric_value is None:
                continue
            metric = self._concept_to_metric.get(_normalized(fact.local_name))
            if (
                metric
                and _scope_matches(fact, query)
                and _context_matches(fact.context, query, target_end)
            ):
                candidates.setdefault(metric, []).append(fact)

        mapped: Dict[str, MetricRecord] = {}
        for metric, facts in candidates.items():
            selected = min(
                facts,
                key=lambda item: (
                    _context_rank(item.context, query, target_end),
                    self._alias_rank[(metric, _normalized(item.local_name))],
                    _namespace_version_rank(item.namespace),
                    item.namespace,
                ),
            )
            mapped[metric] = _reported(metric, selected)
        _derive_metrics(mapped)
        return tuple(mapped[name] for name in sorted(mapped))


def infer_scope(context: ContextRecord) -> StatementScope:
    dimension_text = " ".join(
        (dimension.dimension_name + " " + dimension.member_name).lower()
        for dimension in context.dimensions
    )
    if "consolidated" in dimension_text or "group" in dimension_text:
        return StatementScope.CONSOLIDATED
    if "standalone" in dimension_text or "separate" in dimension_text:
        return StatementScope.STANDALONE
    return StatementScope.UNKNOWN


def _target_accounting_date(
    facts: Iterable[FactRecord], query: ContextQuery
) -> Optional[date]:
    dates = sorted(
        {
            fact.context.accounting_date
            for fact in facts
            if fact.context.accounting_date
            and _period_kind_matches(fact.context, query.period)
        },
        reverse=True,
    )
    index = 0 if query.current else 1
    return dates[index] if len(dates) > index else None


def _period_kind_matches(context: ContextRecord, period: str) -> bool:
    if period == "instant":
        return context.period_kind == PeriodKind.INSTANT
    if context.period_kind != PeriodKind.DURATION:
        return False
    days = _duration_days(context)
    if days is None:
        return False
    return 75 <= days <= 105 if period == "quarter" else 150 <= days <= 380


def _duration_days(context: ContextRecord) -> Optional[int]:
    if context.period_start is None or context.period_end is None:
        return None
    return (context.period_end - context.period_start).days + 1


def _namespace_version_rank(namespace: str) -> Tuple[int, ...]:
    versions = tuple(int(value) for value in re.findall(r"\d+", namespace))
    return tuple(-value for value in versions) if versions else (0,)


def _context_matches(
    context: ContextRecord, query: ContextQuery, target_end: Optional[date]
) -> bool:
    if target_end and context.accounting_date != target_end:
        return False
    if query.period == "instant":
        return context.period_kind == PeriodKind.INSTANT
    if context.period_kind != PeriodKind.DURATION:
        return False
    days = _duration_days(context)
    if days is None:
        return False
    if query.period == "quarter":
        return 75 <= days <= 105
    return 150 <= days <= 380


def _scope_matches(fact: FactRecord, query: ContextQuery) -> bool:
    if query.scope == StatementScope.UNKNOWN:
        return True
    scope = infer_scope(fact.context)
    if scope != StatementScope.UNKNOWN:
        return scope == query.scope
    if fact.filing.consolidated is None:
        return True
    filing_scope = (
        StatementScope.CONSOLIDATED
        if fact.filing.consolidated
        else StatementScope.STANDALONE
    )
    return filing_scope == query.scope


def _context_rank(
    context: ContextRecord, query: ContextQuery, target_end: Optional[date]
) -> Tuple[int, int, str]:
    inferred = infer_scope(context)
    scope_rank = 0 if inferred == query.scope else 1 if inferred == StatementScope.UNKNOWN else 2
    days = _duration_days(context) or 0
    expected = 90 if query.period == "quarter" else 270
    duration_rank = abs(days - expected) if query.period != "instant" else 0
    return scope_rank, duration_rank, context.context_id


def _reported(name: str, fact: FactRecord) -> MetricRecord:
    assert fact.numeric_value is not None
    return MetricRecord(
        filing=fact.filing,
        context=fact.context,
        name=name,
        value=fact.numeric_value,
        unit_ref=fact.unit_ref,
        source=MetricSource.REPORTED,
        concept_qnames=(fact.qname,),
    )


def _derive_metrics(mapped: Dict[str, MetricRecord]) -> None:
    if "ebitda" not in mapped:
        _derive_sum(
            mapped,
            "ebitda",
            ("pbt", "finance_cost", "depreciation_amortisation"),
            "pbt + finance_cost + depreciation_amortisation",
        )
    if "operating_profit" not in mapped:
        if "ebitda" in mapped and "depreciation_amortisation" in mapped:
            _derive(
                mapped,
                "operating_profit",
                mapped["ebitda"].value
                - mapped["depreciation_amortisation"].value,
                ("ebitda", "depreciation_amortisation"),
                "ebitda - depreciation_amortisation",
            )
    if "liabilities" not in mapped and "assets" in mapped and "equity" in mapped:
        _derive(
            mapped,
            "liabilities",
            mapped["assets"].value - mapped["equity"].value,
            ("assets", "equity"),
            "assets - equity",
        )


def _derive_sum(
    mapped: Dict[str, MetricRecord],
    output: str,
    inputs: Sequence[str],
    expression: str,
) -> None:
    if all(name in mapped for name in inputs):
        _derive(
            mapped,
            output,
            sum((mapped[name].value for name in inputs), Decimal(0)),
            inputs,
            expression,
        )


def _derive(
    mapped: Dict[str, MetricRecord],
    output: str,
    value: Decimal,
    inputs: Sequence[str],
    expression: str,
) -> None:
    first = mapped[inputs[0]]
    qnames: List[Tuple[str, str]] = []
    seen: Set[Tuple[str, str]] = set()
    for name in inputs:
        for qname in mapped[name].concept_qnames:
            if qname not in seen:
                seen.add(qname)
                qnames.append(qname)
    mapped[output] = MetricRecord(
        filing=first.filing,
        context=first.context,
        name=output,
        value=value,
        unit_ref=first.unit_ref,
        source=MetricSource.DERIVED,
        concept_qnames=tuple(qnames),
        derivation=expression,
    )

"""Safe typed company screener with SQL-like NULL semantics."""

from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from enum import Enum
from typing import Iterable, List, Mapping, Optional, Protocol, Sequence, Tuple


class Operator(str, Enum):
    EQ = "eq"
    NE = "ne"
    GT = "gt"
    GTE = "gte"
    LT = "lt"
    LTE = "lte"
    IS_NULL = "is_null"
    NOT_NULL = "not_null"


ALLOWED_FIELDS = frozenset(
    {
        "revenue",
        "pat",
        "operating_profit",
        "ebitda",
        "assets",
        "liabilities",
        "equity",
        "debt",
        "cash",
        "current_assets",
        "current_liabilities",
        "finance_cost",
        "depreciation_amortisation",
        "sales_growth",
        "profit_growth",
        "operating_margin",
        "net_margin",
        "roe",
        "roce",
        "debt_equity",
        "current_ratio",
        "market_cap",
        "pe",
        "pb",
        "dividend_yield",
        "high_52w_distance",
        "low_52w_distance",
        "price",
    }
)


@dataclass(frozen=True)
class CompanySnapshot:
    symbol: str
    as_of: date
    period_end: date
    metrics: Mapping[str, Optional[Decimal]]
    prior_metrics: Mapping[str, Optional[Decimal]] = field(default_factory=dict)
    market: Mapping[str, Optional[Decimal]] = field(default_factory=dict)


class SnapshotAdapter(Protocol):
    def snapshots(
        self, as_of: date, symbols: Optional[Sequence[str]] = None
    ) -> Iterable[CompanySnapshot]:
        """Return only information known on or before the requested date."""


@dataclass(frozen=True)
class Condition:
    field: str
    operator: Operator
    value: Optional[Decimal] = None

    def __post_init__(self) -> None:
        if self.field not in ALLOWED_FIELDS:
            raise ValueError("unsupported screener field: {}".format(self.field))
        if self.operator in (Operator.IS_NULL, Operator.NOT_NULL):
            if self.value is not None:
                raise ValueError("{} does not accept a value".format(self.operator.value))
        elif self.value is None:
            raise ValueError("{} requires a numeric value".format(self.operator.value))
        elif not isinstance(self.value, Decimal):
            raise TypeError("condition value must be Decimal")


@dataclass(frozen=True)
class Sort:
    field: str
    descending: bool = False

    def __post_init__(self) -> None:
        if self.field not in ALLOWED_FIELDS and self.field not in ("symbol", "period_end"):
            raise ValueError("unsupported sort field: {}".format(self.field))


@dataclass(frozen=True)
class ScreenRequest:
    as_of: date
    conditions: Tuple[Condition, ...] = ()
    sort: Tuple[Sort, ...] = ()
    limit: int = 100
    symbols: Optional[Tuple[str, ...]] = None

    def __post_init__(self) -> None:
        if self.limit < 1 or self.limit > 10_000:
            raise ValueError("limit must be between 1 and 10000")


@dataclass(frozen=True)
class ScreenResult:
    symbol: str
    as_of: date
    period_end: date
    values: Mapping[str, Optional[Decimal]]


class Screener:
    def __init__(self, adapter: SnapshotAdapter) -> None:
        self.adapter = adapter

    def run(self, request: ScreenRequest) -> Tuple[ScreenResult, ...]:
        results: List[ScreenResult] = []
        for snapshot in self.adapter.snapshots(request.as_of, request.symbols):
            if snapshot.as_of > request.as_of:
                raise ValueError("adapter returned data after requested as_of")
            values = compute_values(snapshot)
            if all(_matches(values.get(item.field), item) for item in request.conditions):
                results.append(
                    ScreenResult(
                        snapshot.symbol,
                        request.as_of,
                        snapshot.period_end,
                        values,
                    )
                )

        for sort in reversed(request.sort):
            present = [
                item for item in results if _sort_value(item, sort.field) is not None
            ]
            missing = [
                item for item in results if _sort_value(item, sort.field) is None
            ]
            present.sort(
                key=lambda item, field=sort.field: _sort_value(item, field),
                reverse=sort.descending,
            )
            results[:] = present + missing
        return tuple(results[: request.limit])


def compute_values(snapshot: CompanySnapshot) -> Mapping[str, Optional[Decimal]]:
    values = {name: snapshot.metrics.get(name) for name in ALLOWED_FIELDS}
    values.update(
        {
            name: snapshot.market.get(name)
            for name in (
                "market_cap",
                "pe",
                "pb",
                "dividend_yield",
                "price",
            )
        }
    )
    revenue = snapshot.metrics.get("revenue")
    pat = snapshot.metrics.get("pat")
    operating_profit = snapshot.metrics.get("operating_profit")
    equity = snapshot.metrics.get("equity")
    assets = snapshot.metrics.get("assets")
    current_liabilities = snapshot.metrics.get("current_liabilities")
    debt = snapshot.metrics.get("debt")
    current_assets = snapshot.metrics.get("current_assets")
    finance_cost = snapshot.metrics.get("finance_cost")
    pbt = snapshot.metrics.get("pbt")
    price = snapshot.market.get("price")
    high_52w = snapshot.market.get("high_52w")
    low_52w = snapshot.market.get("low_52w")

    values["sales_growth"] = _growth(revenue, snapshot.prior_metrics.get("revenue"))
    values["profit_growth"] = _growth(pat, snapshot.prior_metrics.get("pat"))
    values["operating_margin"] = _percent(operating_profit, revenue)
    values["net_margin"] = _percent(pat, revenue)
    values["roe"] = _percent(pat, equity)
    capital_employed = _subtract(assets, current_liabilities)
    ebit = _sum_optional(pbt, finance_cost)
    values["roce"] = _percent(ebit, capital_employed)
    values["debt_equity"] = _divide(debt, equity)
    values["current_ratio"] = _divide(current_assets, current_liabilities)
    values["high_52w_distance"] = _distance(price, high_52w)
    values["low_52w_distance"] = _distance(price, low_52w)
    return values


def _matches(actual: Optional[Decimal], condition: Condition) -> bool:
    if condition.operator == Operator.IS_NULL:
        return actual is None
    if condition.operator == Operator.NOT_NULL:
        return actual is not None
    if actual is None:
        return False
    expected = condition.value
    assert expected is not None
    return {
        Operator.EQ: actual == expected,
        Operator.NE: actual != expected,
        Operator.GT: actual > expected,
        Operator.GTE: actual >= expected,
        Operator.LT: actual < expected,
        Operator.LTE: actual <= expected,
    }[condition.operator]


def _sort_value(result: ScreenResult, field: str) -> object:
    return (
        result.symbol
        if field == "symbol"
        else result.period_end
        if field == "period_end"
        else result.values.get(field)
    )


def _growth(current: Optional[Decimal], prior: Optional[Decimal]) -> Optional[Decimal]:
    if current is None or prior is None or prior == 0:
        return None
    return (current - prior) / abs(prior) * Decimal(100)


def _percent(
    numerator: Optional[Decimal], denominator: Optional[Decimal]
) -> Optional[Decimal]:
    value = _divide(numerator, denominator)
    return value * Decimal(100) if value is not None else None


def _divide(
    numerator: Optional[Decimal], denominator: Optional[Decimal]
) -> Optional[Decimal]:
    if numerator is None or denominator is None or denominator == 0:
        return None
    return numerator / denominator


def _subtract(
    left: Optional[Decimal], right: Optional[Decimal]
) -> Optional[Decimal]:
    if left is None or right is None:
        return None
    return left - right


def _sum_optional(
    left: Optional[Decimal], right: Optional[Decimal]
) -> Optional[Decimal]:
    if left is None or right is None:
        return None
    return left + right


def _distance(price: Optional[Decimal], reference: Optional[Decimal]) -> Optional[Decimal]:
    if price is None or reference is None or reference == 0:
        return None
    return (price - reference) / reference * Decimal(100)
